    LDA a:TextBox_AttributeData,X
    AND #$fc
    STA Temp_Int24_M
    LDA Temp_Int24
    AND #$03
    ORA Temp_Int24_M
    STA a:TextBox_AttributeData,X
    RTS

  @LAB_PRG12__882f:
    LDA a:TextBox_AttributeData,X
    AND #$f3
    STA Temp_Int24_M
    LDA Temp_Int24
    ASL A
    ASL A
    AND #$0c
    ORA Temp_Int24_M
    STA a:TextBox_AttributeData,X
    RTS

  @LAB_PRG12__8842:
    LDA TextBox_ContentsX
    LSR A
    BCS @LAB_PRG12__885c
    LDA a:TextBox_AttributeData,X
    AND #$cf
    STA Temp_Int24_M
    LDA Temp_Int24
    ASL A
    ASL A
    ASL A
    ASL A
    AND #$30
    ORA Temp_Int24_M
    STA a:TextBox_AttributeData,X
    RTS

  @LAB_PRG12__885c:
    LDA a:TextBox_AttributeData,X
    AND #$3f
    STA Temp_Int24_M
