PlayerMenu_Show:
    LDA #$06
    STA a:Arg_StringsCount
    LDA #$00
    STA a:Menu_CursorPos
    LDA #$02
    STA a:TextBox_X
    LDA #$06
    STA a:TextBox_Y
    LDA #$0a
    STA a:TextBox_Width
    LDA #$0e
    STA a:TextBox_Height
    LDA #$18
    JSR Sound_PlayEffect
    JSR TextBox_Open
    LDA #<PLAYER_TOP_MENU_ITEM_STRINGS
    STA Temp_Int24
    LDA #>PLAYER_TOP_MENU_ITEM_STRINGS
    STA Temp_Int24_M
    LDX #$00
    STX a:DataArray
    INX
    STX a:DataArray_1_
    INX
    STX a:DataArray_2_
    INX
    STX a:DataArray_3_
    INX
    STX a:DataArray_4_
    INX
    STX a:DataArray_5_
    JSR PlayerMenu_DrawStringLines

  @_inputLoop:
    JSR WaitForNextFrame
    JSR Screen_ResetSpritesForGamePlay
    JSR Menu_UpdateAndDraw
    LDA Joy1_ChangedButtonMask
    BMI @_loadMenuIDs
    ASL A
    BPL @_inputLoop
    JMP TextBox_Close

  @_loadMenuIDs:
