;============================================================================
TextBox_CheckShouldContinueOrDismissQuestion:
    LDA a:MessageID
    BNE @LAB_PRG12__998e
    JSR TextBox_DrawQuestionMarkTerminatorSymbol
    LDA Joy1_ChangedButtonMask
    BMI TextBox_SetContinueWriteMessage
    BPL TextBox_DismissIfBElseContinue

  @LAB_PRG12__998e:
    LDA a:TextBox_MessagePaused
    BEQ TextBox_DismissIfBElseContinue
    JSR TextBox_DrawDownArrowTerminatorSymbol
    LDA Joy1_ChangedButtonMask
    BPL TextBox_DismissIfBElseContinue
    JSR TextBox_PrepareContinueMessage
    CLC                                     ; Set C=0 to indicate not
                                            ; dismissed.
    LDA #$01                                ; Set A=1 to indicate to
                                            ; continue.

    ;
    ; XREFS:
    ;     TextBox_DrawDownArrowTerminatorSymbol
    ;     TextBox_DrawQuestionMarkTerminatorSymbol
    ;     TextBox_DrawUpArrowTerminatorSymbol
    ;
RETURN_99A0:
    RTS


;============================================================================
; Draw the down arrow terminator symbol.
;
; This will draw the down arrow symbol at the bottom of the
; textbox.
;
; The symbol will appear to flash due to the textbox being
; redrawn in-between viable interrupt-based updates.
;
; INPUTS:
;     InterruptCounter:
;         The current interrupt counter, used to rate limit
;         updates.
;
;     TextBox_X:
;         The tile X position of the textbox.
;
;     TextBox_Y:
;         The tile Y position of the textbox.
;
; OUTPUTS:
;     None.
;
; CALLS:
;     UI_DrawPromptInputSymbol
;
; XREFS:
;     TextBox_CheckForDismiss
;     TextBox_CheckShouldContinue
;     TextBox_CheckShouldContinueOrDismissQuestion
;============================================================================
TextBox_DrawDownArrowTerminatorSymbol:
    LDA InterruptCounter                    ; Load the interrupt counter.
    AND #$10                                ; Is bit 5 set?
    BEQ RETURN_99A0                         ; If not, return (allowing it to
                                            ; clear).


    ;
    ; Compute an X position for the symbol.
    ;
    LDA a:TextBox_X                         ; Load the textbox X coordinate.
    ASL A                                   ; Convert to a pixel position.
    ASL A
    ASL A
    ADC #$4c                                ; Add 76.
    TAX                                     ; X = result.


    ;
    ; Compute a Y position for the symbol.
    ;
    LDA a:TextBox_Y                         ; Load the textbox Y coordinate.
    ASL A                                   ; Convert to a pixel position.
    ASL A
    ASL A
    ADC #$10                                ; Add 16.
    TAY                                     ; Y = result.


    ;
    ; Draw the symbol.
    ;
    LDA #$e5                                ; A = 0xE5 (animation frame
                                            ; offset).
    JMP UI_DrawPromptInputSymbol            ; Draw the symbol.


;============================================================================
; Draw the up arrow terminator symbol.
;
; This will draw the up arrow symbol at the bottom-right of
; the textbox. This is used for the Guru, Add Inventory Item,
; and other textboxes.
;
; The symbol will appear to flash due to the textbox being
; redrawn in-between viable interrupt-based updates.
;
; INPUTS:
;     InterruptCounter:
;         The current interrupt counter, used to rate limit
;         updates.
;
;     TextBox_X:
;         The tile X position of the textbox.
;
;     TextBox_Y:
;         The tile Y position of the textbox.
;
; OUTPUTS:
;     None.
;
; CALLS:
;     UI_DrawPromptInputSymbol
;
; XREFS:
;     IScriptAction_AddInventoryItem
;     IScriptAction_ShowPassword
;     TextBox_CheckShouldContinue
;     TextBox_CheckShouldContinueOrDismissMessage
;============================================================================
TextBox_DrawUpArrowTerminatorSymbol:
    LDA InterruptCounter                    ; Load the interrupt counter.
    AND #$10                                ; Is bit 5 set?
    BEQ RETURN_99A0                         ; If not, return (allowing it to
                                            ; clear).


    ;
    ; Compute an X position for the symbol.
    ;
    LDA a:TextBox_X                         ; Load the textbox X coordinate.
    ASL A                                   ; Convert to a pixel position.
    ASL A
    ASL A
    ADC #$8e                                ; Add 142.
    TAX                                     ; X = result.


    ;
    ; Compute a Y position for the symbol.
    ;
    LDA a:TextBox_Y                         ; Load the textbox Y coordinate.
    ASL A                                   ; Convert to a pixel position.
    ASL A
    ASL A
    ADC #$0e                                ; Add 14.
    TAY                                     ; Y = result.


    ;
    ; Draw the symbol.
    ;
    LDA #$e6                                ; A = 0xE6 (up arrow symbol).
    JMP UI_DrawPromptInputSymbol            ; Draw the symbol.


;============================================================================
; Draw the question mark terminator symbol.
;
; This will draw the question mark symbol at the
; bottom-right of the textbox. This is used for the Guru,
; Add Inventory Item, and other textboxes.
;
; The symbol will appear to flash due to the textbox being
; redrawn in-between viable interrupt-based updates.
;
; INPUTS:
;     InterruptCounter:
;         The current interrupt counter, used to rate limit
;         updates.
;
;     TextBox_X:
;         The tile X position of the textbox.
;
;     TextBox_Y:
;         The tile Y position of the textbox.
;
; OUTPUTS:
;     None.
;
; CALLS:
;     UI_DrawPromptInputSymbol
;
; XREFS:
;     TextBox_CheckShouldContinueOrDismissQuestion
;============================================================================
TextBox_DrawQuestionMarkTerminatorSymbol:
    LDA InterruptCounter                    ; Load the interrupt counter.
    AND #$10                                ; Is bit 5 set?
    BEQ RETURN_99A0                         ; If not, return (allowing it to
                                            ; clear).


    ;
    ; Compute an X position for the symbol.
    ;
    LDA a:TextBox_X                         ; Load the textbox X coordinate.
    ASL A                                   ; Convert to a pixel position.
    ASL A
    ASL A
    ADC #$4c                                ; Add 76.
    TAX                                     ; X = result.


    ;
    ; Compute a Y position for the symbol.
    ;
    LDA a:TextBox_Y                         ; Load the textbox Y coordinate.
    ASL A                                   ; Convert to a pixel position.
    ASL A
    ASL A
    ADC #$10                                ; Add 16.
    TAY                                     ; Y = result.


    ;
    ; Draw the symbol.
    ;
    LDA #$e7                                ; A = 0xE7 (question mark symbol)
    JMP UI_DrawPromptInputSymbol            ; Draw the symbol.

;============================================================================
; TODO: Document Shop_Draw
;
; INPUTS:
;     Y
;
; OUTPUTS:
;     TODO
;
; XREFS:
;     IScriptAction_OpenShop
;     IScriptAction_ShowSellMenu
;============================================================================
Shop_Draw:
    LDA #$0a
    STA a:TextBox_X
    LDA #$08
    STA a:TextBox_Y
    LDA #$14
    STA a:TextBox_Width
    LDA #$14
    STA a:TextBox_Height
    JSR TextBox_Open
    LDA a:TextBox_Y
    CLC
    ADC #$02
    STA TextBox_ContentsY
    LDX #$00
    STX a:Menu_CursorPos

  @LAB_PRG12__9a1c:
    TXA
    PHA
    LDA a:TextBox_X
    CLC
    ADC #$02
    STA TextBox_ContentsX
    TXA
    PHA
    LDA a:DataArray,X
    JSR TextBox_DrawItemImage
    PLA
    TAX
    LDA a:ShopItemCostsU,X
    PHA
    LDA a:ShopItemCostsL,X
    PHA
    LDA a:TextBox_X
    CLC
    ADC #$05
    STA TextBox_ContentsX
    LDA a:DataArray,X
    JSR TextBox_DrawItemName
    PLA
    STA Temp_Int24
    PLA
    STA Temp_Int24_M
    LDA #$00
    STA Temp_Int24_U
    LDA a:TextBox_X
    CLC
    ADC #$0d
    STA TextBox_ContentsX
    INC TextBox_ContentsY
    LDY #$05
    JSR UI_DrawDigitsNoLeadingZeroes
    INC TextBox_ContentsY
    PLA
    TAX
    INX
    CPX a:Arg_StringsCount
    BNE @LAB_PRG12__9a1c
    RTS

;============================================================================
; TODO: Document Player_RemoveItem
;
; INPUTS:
;     A
;
; OUTPUTS:
;     TODO
;
; XREFS:
;     IScriptAction_ConsumeItem
;     IScriptAction_ShowSellMenu
;     Player_Equip
;============================================================================
Player_RemoveItem:
    LDX #$00
    CMP #$80
    BEQ @_isSpecialItem
    INX
    CMP #$81
    BEQ @_isSpecialItem
    INX
    CMP #$82
    BEQ @_isSpecialItem
    INX
    CMP #$83
    BEQ @_isSpecialItem
    INX
    CMP #$92
    BEQ @_isSpecialItem
    INX
    CMP #$8a
    BEQ @_isSpecialItem
    INX
    CMP #$93
    BEQ @_isSpecialItem
    INX
    CMP #$94
    BEQ @_isSpecialItem
    STA Temp_Int24_U
    JSR Player_GetInventoryIndexForItem
    TAX
    LDA a:NumberOfWeapons,X
    BEQ @_return
    STA Temp_0xEF
    LDA a:INVENTORY_CATEGORY_L,X
    STA Temp_Int24
    LDA a:INVENTORY_CATEGORY_U,X
    STA Temp_Int24_M
    LDY #$00
    LDA Temp_Int24_U
    AND #$1f

  @_inventoryCheckLoop:
    CMP (Temp_Int24),Y
    BEQ @_moveInventoryLoop
    INY
    CPY Temp_0xEF
    BNE @_inventoryCheckLoop
    RTS

  @_moveInventoryLoop:
    INY
    CPY Temp_0xEF
    BEQ @_updateCountAndReturn
    LDA (Temp_Int24),Y
    DEY
    STA (Temp_Int24),Y
    INY
    BNE @_moveInventoryLoop

  @_updateCountAndReturn:
    DEC a:NumberOfWeapons,X

  @_return:
    RTS

  @_isSpecialItem:
    LDA a:SpecialItems
    AND a:SHOP_ITEM_TO_CLEAR_SPECIAL_ITEM_BITS,X
    STA a:SpecialItems
    RTS

;
; XREFS:
;     Player_RemoveItem
;
SHOP_ITEM_TO_CLEAR_SPECIAL_ITEM_BITS:
    .byte $7f                               ; [0]: Clear Ring of Elf

;
; XREFS:
;     Player_RemoveItem
;
SHOP_ITEM_TO_CLEAR_SPECIAL_ITEM_BITS_1_:
    .byte $bf                               ; [1]: Clear Ring of Ruby

;
; XREFS:
;     Player_RemoveItem
;
SHOP_ITEM_TO_CLEAR_SPECIAL_ITEM_BITS_2_:
    .byte $df                               ; [2]: Clear Ring of Dworf

;
; XREFS:
;     Player_RemoveItem
;
SHOP_ITEM_TO_CLEAR_SPECIAL_ITEM_BITS_3_:
    .byte $ef                               ; [3]: Clear Demon's Ring

;
; XREFS:
;     Player_RemoveItem
;
SHOP_ITEM_TO_CLEAR_SPECIAL_ITEM_BITS_4_:
    .byte $f7                               ; [4]: Clear Elixir

;
; XREFS:
;     Player_RemoveItem
;
SHOP_ITEM_TO_CLEAR_SPECIAL_ITEM_BITS_5_:
    .byte $fb                               ; [5]: Clear Magical Rod

;
; XREFS:
;     Player_RemoveItem
;
SHOP_ITEM_TO_CLEAR_SPECIAL_ITEM_BITS_6_:
    .byte $fd                               ; [6]: Clear Pendant

;
; XREFS:
;     Player_RemoveItem
;
SHOP_ITEM_TO_CLEAR_SPECIAL_ITEM_BITS_7_:
    .byte $fe                               ; [7]: Clear Black Onyx

SPECIAL_ITEM_IDS:
    .byte SPECIAL_RING_OF_ELF               ; [0]:
    .byte SPECIAL_RING_OF_RUBY              ; [1]:
    .byte SPECIAL_RING_OF_DWORF             ; [2]:
    .byte SPECIAL_DEMONS_RING               ; [3]:
    .byte SPECIAL_ELIXIR                    ; [4]:
    .byte SPECIAL_MAGICAL_ROD               ; [5]:

;
; XREFS:
;     Player_AddToInventory
;
SPECIAL_ITEM_IDS_6_:
    .byte SPECIAL_PENDANT                   ; [6]:

;
; XREFS:
;     Player_AddToInventory
;
SPECIAL_ITEM_IDS_7_:
    .byte SPECIAL_BLACK_ONYX                ; [7]:

SPECIAL_ITEM_BITMASKS:
    .byte $80                               ; [0]:
    .byte $40                               ; [1]:
    .byte $20                               ; [2]:
    .byte $10                               ; [3]:
    .byte $08                               ; [4]:
    .byte $04                               ; [5]:
    .byte $02                               ; [6]:

;
; XREFS:
;     Player_AddSpecialItem
;
BYTE_PRG12__9aec:
    .byte $01                               ; byte

;============================================================================
; TODO: Document Player_AddSpecialItem
;
; INPUTS:
;     X
;
; OUTPUTS:
;     TODO
;
; XREFS:
;     Player_AddToInventory
;============================================================================
Player_AddSpecialItem:
    LDA a:SpecialItems
    ORA a:SPECIAL_ITEM_BITMASKS,X
    STA a:SpecialItems
    RTS

;============================================================================
; TODO: Document Player_AddToInventory
;
; INPUTS:
;     A
;
; OUTPUTS:
;     TODO
;
; XREFS:
;     IScriptAction_AddInventoryItem
;     IScriptAction_OpenShop
;     Player_Equip
;============================================================================
Player_AddToInventory:
    LDX #$07                                ; i = 7; Loop through item bits.

  @_checkSpecialItems:
    CMP a:SPECIAL_ITEM_IDS,X                ; Check if this is a special,
                                            ; non-consumable item
    BEQ Player_AddSpecialItem               ; If this is a special item...
    DEX                                     ; Next i
    BPL @_checkSpecialItems
    STA Temp_Int24_U
    JSR Player_GetInventoryIndexForItem     ; Convert the item ID to a
                                            ; category.
    TAX
    LDA a:INVENTORY_CATEGORY_L,X
    STA Temp_Int24
    LDA a:INVENTORY_CATEGORY_U,X
    STA Temp_Int24_M


    ;
    ; Check if the maximum has been reached for the inventory category.
    ;
    LDA a:NumberOfWeapons,X                 ; Load the number of items in the
                                            ; inventory category
    CMP a:MAX_INVENTORY_SLOTS,X             ; Check if the max has been hit
    BNE @_addItem
    DEC a:NumberOfWeapons,X                 ; The max has been hit. Remove
                                            ; one.

  @_addItem:
    LDY a:NumberOfWeapons,X
    LDA Temp_Int24_U
    AND #$1f
    STA (Temp_Int24),Y
    INC a:NumberOfWeapons,X                 ; Increase the length of the
                                            ; inventory
    RTS


