;============================================================================
; TODO: Document UI_DrawText
;
; INPUTS:
;     None.
;
; OUTPUTS:
;     A
;
; XREFS:
;     PasswordScreen_Show
;     StartScreen_Draw
;============================================================================
UI_DrawText:
    LDY #$00

  @_loop:
    LDA (Temp_Int24),Y
    BEQ @_return
    CMP #$20
    BNE @_writePPUData
    LDA #$00

  @_writePPUData:
    STA a:PPUDATA
    INY
    BNE @_loop

  @_return:
    RTS

;============================================================================
; TODO: Document StartScreen_Draw
;
; INPUTS:
;     None.
;
; OUTPUTS:
;     TODO
;============================================================================
StartScreen_Draw:
    JSR PPU_WaitUntilFlushed


    ;
    ; Write 224 Faxanadu logo tiles
    ;
    ; From: CHR ROM: Bank 10, 0x8E00: CHR_FAXANADU_LOGO
    ; To:   CHR RAM: 0x1000
    ;
    LDA #<CHR_FAXANADU_LOGO
    STA IScriptOrCHRAddr
    LDA #>CHR_FAXANADU_LOGO
    STA IScriptOrCHRAddr_U
    LDA #$00
    STA PPU_TargetAddr
    LDA #$10
    STA PPU_TargetAddr_U
    LDX #$0a
    LDY #$e0
    JSR PPU_WriteTilesFromCHRRAM


    ;
    ; Write 27 letter tiles:
    ;
    ; From: CHR ROM: Bank 10, 0x8240: CHR_LETTERS
    ; To:   CHR RAM: 0x1E00
    ;
    LDA #<CHR_LETTERS
    STA IScriptOrCHRAddr
    LDA #>CHR_LETTERS
    STA IScriptOrCHRAddr_U
    LDA #$00
    STA PPU_TargetAddr
    LDA #$1e
    STA PPU_TargetAddr_U
    LDX #$0a
    LDY #$1b
    JSR PPU_WriteTilesFromCHRRAM


    ;
    ; Write 10 number tiles:
    ;
    ; From: CHR ROM: Bank 10, 0x8440: CHR_NUMBERS
    ; To:   CHR RAM: 0x1D60
    ;
    LDA #<CHR_NUMBERS
    STA IScriptOrCHRAddr
    LDA #>CHR_NUMBERS
    STA IScriptOrCHRAddr_U
    LDA #$60
    STA PPU_TargetAddr
    LDA #$1d
    STA PPU_TargetAddr_U
    LDX #$0a
    LDY #$0a
    JSR PPU_WriteTilesFromCHRRAM
    JSR PPU_ClearAllTilemaps


    ;
    ; Write 4 attribute values
    ;
    ; From: Bank 10, 0x9B60: PRG10:9B60
    ; To:   Attribute table: 0x23C0
    ;
    LDA #<START_SCREEN_PPU_ATTRIBUTES
    STA IScriptOrCHRAddr
    LDA #>START_SCREEN_PPU_ATTRIBUTES
    STA IScriptOrCHRAddr_U
    LDA #$c0
    STA PPU_TargetAddr
    LDA #$23
    STA PPU_TargetAddr_U
    LDX #$0a
    LDY #$04
    JSR PPU_WriteTilesFromCHRRAM


    ;
    ; Set to top-left of bordered Faxanadu logo (0x2042) and draw
    ; the tiles.
    ;
    ; Copy from the CHR RAM we populated earlier, drawing from the
    ; bottom row to the top.
    ;
    LDA #$20
    STA a:PPUADDR
    LDA #$42
    STA a:PPUADDR
    LDA #$00
    STA Temp_Int24
    LDA #>START_SCREEN_LOGO_TILES
    STA Temp_Int24_M
    LDY #$00
    LDA #<START_SCREEN_LOGO_TILES
    STA Temp_Int24_U

  @LAB_PRG12__9e9b:
    LDX #$1c

  @LAB_PRG12__9e9d:
    LDA (Temp_Int24),Y
    STA a:PPUDATA
    INY
    BNE @LAB_PRG12__9ea7
    INC Temp_Int24_M

  @LAB_PRG12__9ea7:
    DEX
    BNE @LAB_PRG12__9e9d
    LDA #$00
    STA a:PPUDATA
    STA a:PPUDATA
    STA a:PPUDATA
    STA a:PPUDATA
    DEC Temp_Int24_U
    BNE @LAB_PRG12__9e9b
    LDA #$00
    STA a:DAT_0687


    ;
    ; Set position to the start of "START" (0x2288) and
    ; draw the text tiles.
    ;
    LDA #$22
    STA a:PPUADDR
    LDA #$88
    STA a:PPUADDR
    LDA #<TEXT_TILES_START
    STA Temp_Int24
    LDA #>TEXT_TILES_START
    STA Temp_Int24_M
    JSR UI_DrawText


    ;
    ; Set position to the start of "CONTINUE" (0x2290) and
    ; draw the text tiles.
    ;
    LDA #$22
    STA a:PPUADDR
    LDA #$90
    STA a:PPUADDR
    LDA #<TEXT_TILES_CONTINUE
    STA Temp_Int24
    LDA #>TEXT_TILES_CONTINUE
    STA Temp_Int24_M
    JSR UI_DrawText


    ;
    ; Set position to the start of "(C) 1988 Hudson Soft" (0x22E7)
    ; and draw the text tiles.
    ;
    LDA #$22
    STA a:PPUADDR
    LDA #$e7
    STA a:PPUADDR
    LDA #<TEXT_TILES_COPYRIGHT_1998_HUDSON_SOFT
    STA Temp_Int24
    LDA #>TEXT_TILES_COPYRIGHT_1998_HUDSON_SOFT
    STA Temp_Int24_M
    JSR UI_DrawText


    ;
    ; Set position to the start of "Under license from Falcom" (0x2423)
    ; and draw the text tiles.
    ;
    LDA #$23
    STA a:PPUADDR
    LDA #$24
    STA a:PPUADDR
    LDA #<TEXT_TILES_UNDER_LICENSE_FROM_FALCOM
    STA Temp_Int24
    LDA #>TEXT_TILES_UNDER_LICENSE_FROM_FALCOM
    STA Temp_Int24_M
    JSR UI_DrawText


    ;
    ; Set position to the start of "Licensed to Nintendo" (0x2366)
    ; and draw the text tiles.
    ;
    LDA #$23
    STA a:PPUADDR
    LDA #$66
    STA a:PPUADDR
    LDA #<TEXT_TILES_LICENSED_TO_NINTENDO
    STA Temp_Int24
    LDA #>TEXT_TILES_LICENSED_TO_NINTENDO
    STA Temp_Int24_M
    JSR UI_DrawText
    LDA #$10
    JSR Screen_LoadUIPalette
    LDX #$0f

  @LAB_PRG12__9f31:
    LDA a:STARTSCREEEN_PALETTE_SPRITES,X
    STA a:Screen_PaletteData_Sprites,X
    DEX
    BPL @LAB_PRG12__9f31
    JSR PPUBuffer_WritePalette
    LDA #$01
    STA Music_Current
    JMP Screen_ResetForNonGame

;============================================================================
; TODO: Document StartScreen_CheckHandleInput
;
; INPUTS:
;     None.
;
; OUTPUTS:
;     TODO
;============================================================================
StartScreen_CheckHandleInput:
    LDA Joy1_ChangedButtonMask
    AND #$20
    BEQ @LAB_PRG12__9f57
    LDA a:DAT_0687
    EOR #$01
    STA a:DAT_0687
    LDA #$0b
    JSR Sound_PlayEffect

  @LAB_PRG12__9f57:
    LDY #$00
    LDA a:DAT_0687
    BEQ @_drawCurrentItemSymbol
    INY


    ;
    ; Draw the symbol used to show the current menu item selection.
    ;
  @_drawCurrentItemSymbol:
    LDX a:BYTE_ARRAY_PRG12__9f69,Y          ; X = menu item X position.
    LDY #$7e                                ; Y = 126.
    LDA #$ad                                ; A = 0xAD (right arrow symbol)
    JMP UI_DrawPromptInputSymbol            ; Draw the symbol.

;
; XREFS:
;     StartScreen_CheckHandleInput
;
BYTE_ARRAY_PRG12__9f69:
    .byte $34                               ; [0]:
    .byte $74                               ; [1]:


