;============================================================================
; Walking man shown when you enter the first town.
;
; If the player has no gold, they'll be told to see
; the king. Otherwise, they're given directions to
; Apolune.
;
; XREFS:
;     ISCRIPT_ADDRS_L [$PRG12::9f6c]
;     ISCRIPT_ADDRS_U [$PRG12::a004]
