                                                   ; and update if needed.
    pointer ISCRIPT_COMMON_GURU_NEW_RANK    ; If set, jump to show the new
                                            ; rank.
    .byte ISCRIPT_ACTION_JUMP               ; Else, jump to show the new
                                            ; password.
    pointer ISCRIPT_COMMON_GURU_PASSWORD    ; ISCRIPT_COMMON_GURU_PASSWORD


